# Arnoldi `expintegrator` cases (non-normal `outliers` matrices from
# arnoldi.jl, p = nu - 1 or 1); included by generate.jl after arnoldi.jl.
function arnexpcase(out, name, seed, n, iscomplex, nu, t, krylovdim, tol, eager)
    g = SplitMix(seed)
    A = outliers(g, n, iscomplex)
    u = Tuple(startvec(g, n, iscomplex) for _ in 1:nu)
    alg = Arnoldi(; krylovdim, tol, maxiter = 100, eager, orth = ClassicalGramSchmidt2())
    y, info = expintegrator(A, t, u, alg)
    println(out, "case ", name)
    println(out, "complex ", Int(iscomplex))
    println(out, "seed ", seed, "\nn ", n, "\nnu ", nu)
    println(out, "t ", repr(real(t)), " ", repr(imag(t)))
    println(out, "krylovdim ", krylovdim, "\ntol ", repr(tol), "\neager ", Int(eager))
    println(out, "y_re ", fmt(real.(y)))
    println(out, "y_im ", fmt(imag.(y)))
    println(out, "normres ", repr(info.normres))
    println(out, "converged ", info.converged, "\nnumiter ", info.numiter, "\nnumops ", info.numops)
    return println(out, "end")
end

arnexpcase(out, "real_p1_exponentiate", 61, 60, false, 1, -1.0, 12, 1e-12, false)
arnexpcase(out, "real_p1", 62, 60, false, 2, -0.5, 10, 1e-12, false)
arnexpcase(out, "real_p2_eager", 63, 50, false, 3, -1.5, 15, 1e-12, true)
arnexpcase(out, "real_p3", 64, 60, false, 4, -1.0, 10, 1e-12, false)
arnexpcase(out, "complex_v_real_t_p2", 65, 60, true, 3, -0.8, 12, 1e-12, false)
arnexpcase(out, "complex_t_p1", 66, 60, true, 2, -2.0im, 15, 1e-12, false)
arnexpcase(out, "complex_t_p3_eager", 67, 50, true, 4, complex(-0.5, 1.0), 20, 1e-12, true)
arnexpcase(out, "complex_t_exponentiate", 68, 60, true, 1, -3.0im, 12, 1e-12, false)
arnexpcase(out, "complex_t_p2_eager_restart", 69, 50, true, 3, -4.0im, 8, 1e-12, true)
arnexpcase(out, "real_p1_eager_restart", 70, 50, false, 2, -2.0, 6, 1e-12, true)
